import{_ as l,a0 as r,w as p,s as h,ao as a,I as i,a1 as n,A as o,x as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const P=JSON.parse('{"title":"在 Linux 终端中自定义 Bash 配色和提示内容 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 终端中自定义 Bash 配色和提示内容 | LCTT (201701) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 终端中自定义 Bash 配色和提示内容 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 终端中自定义 Bash 配色和提示内容 | LCTT (201701) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201701/20170103 How to Customize Bash Colors and Content in Linux Terminal Prompt copy","title":"在 Linux 终端中自定义 Bash 配色和提示内容","tag":"201701","desc":""},"relativePath":"201701/20170103 How to Customize Bash Colors and Content in Linux Terminal Prompt copy.md","filePath":"[post].md"}'),d={name:"201701/20170103 How to Customize Bash Colors and Content in Linux Terminal Prompt copy.md"};function u(m,t,g,b,T,c){const e=r("Link");return p(),h("div",null,[t[19]||(t[19]=a(`<h1 id="在-linux-终端中自定义-bash-配色和提示内容" tabindex="-1">在 Linux 终端中自定义 Bash 配色和提示内容 <a class="header-anchor" href="#在-linux-终端中自定义-bash-配色和提示内容" aria-label="Permalink to “在 Linux 终端中自定义 Bash 配色和提示内容”">​</a></h1><p>现今，大多数（如果不是全部的话）现代 Linux 发行版的默认 shell 都是 Bash。然而，你可能已经注意到这样一个现象，在各个发行版中，其终端配色和提示内容都各不相同。</p><p>如果你一直都在考虑，或者只是一时好奇，如何定制可以使 Bash 更好用。不管怎样，请继续读下去 —— 本文将告诉你怎么做。</p><h3 id="ps1-bash-环境变量" tabindex="-1">PS1 Bash 环境变量 <a class="header-anchor" href="#ps1-bash-环境变量" aria-label="Permalink to “PS1 Bash 环境变量”">​</a></h3><p>命令提示符和终端外观是通过一个叫 <code>PS1</code> 的变量来进行管理的。根据 <strong>Bash</strong> 手册页说明，<strong>PS1</strong> 代表了 shell 准备好读取命令时显示的主体的提示字符串。</p><p><strong>PS1</strong> 所允许的内容包括一些反斜杠转义的特殊字符，可以查看手册页中 <strong>PRMPTING</strong> 部分的内容来了解它们的含义。</p><p>为了演示，让我们先来显示下我们系统中 <code>PS1</code> 的当前内容吧（这或许看上去和你们的有那么点不同）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo $PS1</span></span>
<span class="line"><span>[\\u@\\h \\W]\\$</span></span></code></pre></div><p>现在，让我们来了解一下怎样自定义 PS1 吧，以满足我们各自的需求。</p><h4 id="自定义-ps1-格式" tabindex="-1">自定义 PS1 格式 <a class="header-anchor" href="#自定义-ps1-格式" aria-label="Permalink to “自定义 PS1 格式”">​</a></h4><p>根据手册页 PROMPTING 章节的描述，下面对各个特殊字符的含义作如下说明：</p><ul><li><code>\\u:</code> 显示当前用户的 <strong>用户名</strong>。</li><li><code>\\h:</code> <ruby>完全限定域名 <rt>Fully-Qualified Domain Name</rt></ruby>（FQDN）中第一个点（.）之前的<strong>主机名</strong>。</li><li><code>\\W:</code> 当前工作目录的<strong>基本名</strong>，如果是位于 <code>$HOME</code> （家目录）通常使用波浪符号简化表示（<code>~</code>）。</li><li><code>\\$:</code> 如果当前用户是 root，显示为 <code>#</code>，否则为 <code>$</code>。</li></ul><p>例如，如果我们想要显示当前命令的历史数量，可以考虑添加 <code>\\!</code>；如果我们想要显示 FQDN 全称而不是短服务器名，那么可以考虑添加 <code>\\H</code>。</p><p>在下面的例子中，我们同时将这两个特殊字符引入我们当前的环境中，命令如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>PS1=&quot;[\\u@\\H \\W \\!]\\$&quot;</span></span></code></pre></div><p>当按下回车键后，你将会看到提示内容会变成下面这样。可以对比执行命令修改前和修改后的提示内容：</p>`,16)),i("p",null,[n(e,{href:"http://www.tecmint.com/wp-content/uploads/2017/01/Customize-Linux-Terminal-Prompt.png"},{default:o(()=>[...t[0]||(t[0]=[i("img",{src:"http://www.tecmint.com/wp-content/uploads/2017/01/Customize-Linux-Terminal-Prompt.png",alt:"Customize Linux Terminal Prompt PS1"},null,-1)])]),_:1})]),t[20]||(t[20]=a("<p><em>自定义 Linux 终端提示符 PS1</em></p><p>现在，让我们再深入一点，修改命令提示符中的用户名和主机名 —— 同时修改文本和环境背景。</p><p>实际上，我们可以对提示符进行 3 个方面的自定义：</p><table><tr><th>文本格式</th><th>前景色（文本）</th><th>背景色 </th></tr><tr><th>0: 常规文本</th><th>30: 黑色</th><th>40: 黑色</th></tr><tr><th>1: 加粗</th><th>31: 红色</th><th>41: 红色</th></tr><tr><th>4: 下划线文本</th><th> 32: 绿色</th><th>42: 绿色</th></tr><tr><th></th><th>33: 黄色</th><th>43: 黄色</th></tr><tr><th></th><th>34: 蓝色</th><th>44: 蓝色</th></tr><tr><th></th><th>35: 紫色</th><th>45: 紫色</th></tr><tr><th></th><th>36: 青色</th><th>46: 青色</th></tr><tr><th></th><th>37: 白色</th><th>47: 白色</th></tr></table><p>我们将在开头使用 <code>\\e</code> 特殊字符，跟着颜色序列，在结尾使用 <code>m</code> 来表示结束。</p><p>在该序列中，三个值（<strong>背景</strong>，<strong>格式</strong>和<strong>前景</strong>）由分号分隔（如果不赋值，则假定为默认值）。</p>",6)),i("p",null,[t[2]||(t[2]=i("strong",null,"建议阅读：",-1)),t[3]||(t[3]=s(" ",-1)),n(e,{href:"http://www.tecmint.com/category/bash-shell/"},{default:o(()=>[...t[1]||(t[1]=[s("在 Linux 中学习 Bash shell 脚本",-1)])]),_:1}),t[4]||(t[4]=s("。",-1))]),t[21]||(t[21]=a('<p>此外，由于值的范围不同，指定背景，格式，或者前景的先后顺序没有关系。</p><p>例如，下面的 <code>PS1</code> 将导致提示符为黄色带下划线文本，并且背景为红色：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>PS1=&quot;\\e[41;4;33m[\\u@\\h \\W]$ &quot;</span></span></code></pre></div>',3)),i("p",null,[n(e,{href:"http://www.tecmint.com/wp-content/uploads/2017/01/Change-Linux-Terminal-Color-Prompt.png"},{default:o(()=>[...t[5]||(t[5]=[i("img",{src:"http://www.tecmint.com/wp-content/uploads/2017/01/Change-Linux-Terminal-Color-Prompt.png",alt:"Change Linux Terminal Color Prompt PS1"},null,-1)])]),_:1})]),t[22]||(t[22]=a('<p><em>修改 Linux 终端提示符配色 PS1</em></p><p>虽然它看起来那么漂亮，但是这个自定义将只会持续到当前用户会话结束。如果你关闭终端，或者退出本次会话，所有修改都会丢失。</p><p>为了让修改永久生效，你必须将下面这行添加到 <code>~/.bashrc</code>或者 <code>~/.bash_profile</code>，这取决于你的版本。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>PS1=&quot;\\e[41;4;33m[\\u@\\h \\W]$ &quot;</span></span></code></pre></div><p>尽情去玩耍吧，你可以尝试任何色彩，直到找出最适合你的。</p><h5 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to “小结”">​</a></h5><p>在本文中，我们讲述了如何来自定义 Bash 提示符的配色和提示内容。如果你对本文还有什么问题或者建议，请在下面评论框中写下来吧。我们期待你们的声音。</p><hr><p>作者简介：Aaron Kili 是一位 Linux 及 F.O.S.S 的狂热爱好者，一位未来的 Linux 系统管理员，web 开发者，而当前是 TechMint 的原创作者，他热爱计算机工作，并且信奉知识分享。</p><p><img src="http://1.gravatar.com/avatar/4e444ab611c7b8c7bcb76e58d2e82ae0?s=128&amp;d=blank&amp;r=g" alt=""></p><hr>',11)),i("p",null,[t[7]||(t[7]=s("via: ",-1)),n(e,{href:"http://www.tecmint.com/customize-bash-colors-terminal-prompt-linux/"},{default:o(()=>[...t[6]||(t[6]=[s("http://www.tecmint.com/customize-bash-colors-terminal-prompt-linux/",-1)])]),_:1})]),i("p",null,[t[11]||(t[11]=s("作者：",-1)),n(e,{href:"http://www.tecmint.com/author/aaronkili/"},{default:o(()=>[...t[8]||(t[8]=[s("Aaron Kili",-1)])]),_:1}),t[12]||(t[12]=s(" 译者：",-1)),n(e,{href:"https://github.com/GOLinux"},{default:o(()=>[...t[9]||(t[9]=[s("GOLinux",-1)])]),_:1}),t[13]||(t[13]=s(" 校对：",-1)),n(e,{href:"https://github.com/jasminepeng"},{default:o(()=>[...t[10]||(t[10]=[s("jasminepeng",-1)])]),_:1})]),i("p",null,[t[16]||(t[16]=s("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[14]||(t[14]=[s("LCTT",-1)])]),_:1}),t[17]||(t[17]=s(" 原创编译，",-1)),n(e,{href:"https://linux.cn/"},{default:o(()=>[...t[15]||(t[15]=[s("Linux中国",-1)])]),_:1}),t[18]||(t[18]=s(" 荣誉推出",-1))])])}const k=l(d,[["render",u]]);export{P as __pageData,k as default};
